public class OrderPayloadParser {

    public class PayloadException extends Exception {}

    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;
    }

    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines;
        public Decimal total;
    }

    public static Order parse(String body) {
        if (String.isBlank(body)) {
            throw new PayloadException('Body is null or blank');
        }

        Object parsed;
        try {
            parsed = JSON.deserializeUntyped(body);
        } catch (Exception e) {
            throw new PayloadException('Invalid JSON: ' + e.getMessage());
        }

        if (!(parsed instanceof Map)) {
            throw new PayloadException('JSON is not an object');
        }

        Map<String, Object> root = (Map<String, Object>) parsed;

        // Validate and extract order number
        if (!root.containsKey('number') || String.isBlank((String) root.get('number'))) {
            throw new PayloadException('Missing or blank order number');
        }
        String orderNumber = (String) root.get('number');

        // Extract order date
        Date orderDate = null;
        if (root.containsKey('date')) {
            String dateStr = (String) root.get('date');
            if (String.isNotBlank(dateStr)) {
                try {
                    orderDate = Date.valueOf(dateStr);
                } catch (Exception e) {
                    throw new PayloadException('Invalid date format');
                }
            }
        }

        // Extract currency
        String currencyCode = null;
        if (root.containsKey('currency')) {
            currencyCode = (String) root.get('currency');
        }

        // Extract customer email
        String customerEmail = null;
        if (root.containsKey('customer')) {
            Object customerObj = root.get('customer');
            if (customerObj instanceof Map) {
                Map<String, Object> customer = (Map<String, Object>) customerObj;
                if (customer.containsKey('email')) {
                    customerEmail = (String) customer.get('email');
                }
            }
        }

        // Extract lines
        List<Line> lines = new List<Line>();
        if (root.containsKey('lines')) {
            Object linesObj = root.get('lines');
            if (linesObj instanceof List) {
                List<Object> linesList = (List<Object>) linesObj;
                for (Object lineObj : linesList) {
                    if (!(lineObj instanceof Map)) {
                        throw new PayloadException('Line item is not an object');
                    }
                    Map<String, Object> lineMap = (Map<String, Object>) lineObj;

                    // Validate sku
                    if (!lineMap.containsKey('sku') || String.isBlank((String) lineMap.get('sku'))) {
                        throw new PayloadException('Missing or blank sku in line item');
                    }
                    String sku = (String) lineMap.get('sku');

                    // Validate quantity
                    if (!lineMap.containsKey('quantity')) {
                        throw new PayloadException('Missing quantity in line item');
                    }
                    Integer quantity;
                    Object qtyObj = lineMap.get('quantity');
                    if (qtyObj instanceof Integer) {
                        quantity = (Integer) qtyObj;
                    } else if (qtyObj instanceof Decimal) {
                        quantity = ((Decimal) qtyObj).intValue();
                    } else {
                        throw new PayloadException('Invalid quantity');
                    }
                    if (quantity <= 0) {
                        throw new PayloadException('Quantity must be positive');
                    }

                    // Validate unitPrice
                    if (!lineMap.containsKey('unitPrice')) {
                        throw new PayloadException('Missing unitPrice in line item');
                    }
                    Decimal unitPrice = (Decimal) lineMap.get('unitPrice');
                    if (unitPrice < 0) {
                        throw new PayloadException('unitPrice must be non-negative');
                    }

                    // Extract discount (default 0)
                    Decimal discount = 0.0;
                    if (lineMap.containsKey('discount')) {
                        Object discountObj = lineMap.get('discount');
                        if (discountObj != null) {
                            discount = (Decimal) discountObj;
                        }
                    }

                    // Calculate lineTotal
                    Decimal lineTotal = quantity * unitPrice * (1 - discount);
                    lineTotal = lineTotal.setScale(2, RoundingMode.HALF_UP);

                    Line line = new Line();
                    line.sku = sku;
                    line.quantity = quantity;
                    line.unitPrice = unitPrice;
                    line.discount = discount;
                    line.lineTotal = lineTotal;
                    lines.add(line);
                }
            }
        }

        // Calculate total
        Decimal total = 0.0;
        for (Line line : lines) {
            total += line.lineTotal;
        }
        total = total.setScale(2, RoundingMode.HALF_UP);

        // Build Order object
        Order order = new Order();
        order.orderNumber = orderNumber;
        order.orderDate = orderDate;
        order.currencyCode = currencyCode;
        order.customerEmail = customerEmail;
        order.lines = lines;
        order.total = total;

        return order;
    }

    public static String toAcknowledgement(Order order) {
        Map<String, Object> acknowledgement = new Map<String, Object>();
        acknowledgement.put('number', order.orderNumber);
        acknowledgement.put('status', 'RECEIVED');
        acknowledgement.put('lineCount', order.lines.size());
        acknowledgement.put('total', order.total);

        return JSON.serialize(acknowledgement);
    }
}
