@isTest
public class AddressVerificationServiceTest {

    // Inner class implementing HttpCalloutMock to simulate the address API callout
    public class AddressVerificationMock implements HttpCalloutMock {
        private HttpResponse mockResponse;
        public HttpRequest recordedRequest;

        public AddressVerificationMock(HttpResponse response) {
            this.mockResponse = response;
        }

        public HttpResponse respond(HttpRequest req) {
            this.recordedRequest = req;
            return mockResponse;
        }
    }

    @isTest
    private static void testVerifyWithBlankBillingStreet() {
        // Account with blank BillingStreet should return SKIPPED without callout
        Account acct = new Account(BillingStreet = '');
        AddressVerificationService.Result result = AddressVerificationService.verify(acct);

        System.assertEquals('SKIPPED', result.status);
        System.assertFalse(result.changed);
    }

    @isTest
    private static void testVerifyWithNonBlankBillingStreetAnd200ResponseVerified() {
        // Setup mock for 200 response with status "VERIFIED"
        HttpResponse mockResp = new HttpResponse();
        mockResp.setStatusCode(200);
        mockResp.setBody('{"status": "VERIFIED", "address": {"street": "123 Main St", "city": "Boston", "postalCode": "02101", "country": "USA"}}');

        AddressVerificationMock mock = new AddressVerificationMock(mockResp);
        Test.setMock(HttpCalloutMock.class, mock);

        Account acct = new Account(BillingStreet = '456 Old St', BillingCity = 'Cambridge', BillingPostalCode = '02139', BillingCountry = 'USA');
        AddressVerificationService.Result result = AddressVerificationService.verify(acct);

        System.assertEquals('VERIFIED', result.status);
        System.assertFalse(result.changed);
        // Account should remain unchanged
        System.assertEquals('456 Old St', acct.BillingStreet);
        System.assertEquals('Cambridge', acct.BillingCity);
        System.assertEquals('02139', acct.BillingPostalCode);
        System.assertEquals('USA', acct.BillingCountry);

        // Verify the callout request details
        HttpRequest req = mock.recordedRequest;
        System.assertEquals('callout:FB_Address_API/v2/verify', req.getEndpoint());
        System.assertEquals('POST', req.getMethod());
        System.assertEquals('application/json', req.getHeader('Content-Type'));

        // Verify the request body
        Map<String, Object> bodyMap = (Map<String, Object>) JSON.deserializeUntyped(req.getBody());
        System.assertEquals('456 Old St', bodyMap.get('street'));
        System.assertEquals('Cambridge', bodyMap.get('city'));
        System.assertEquals('02139', bodyMap.get('postalCode'));
        System.assertEquals('USA', bodyMap.get('country'));
    }

