@isTest
public class OpportunityWonHandlerTest {

    private static final String WON_STAGE = 'Closed Won';
    private static final String HANDOVER_STEP = 'Handover to Customer Success';
    private static final String TASK_SUBJECT = 'Customer kick-off';
    private static final String TASK_PRIORITY = 'High';

    @testSetup
    static void setup() {
        Account testAccount = new Account(Name = 'Test Account', Rating = 'Warm');
        insert testAccount;
    }

    @isTest
    static void testBeforeInsert_NewlyWonOpp() {
        Account testAccount = [SELECT Id FROM Account LIMIT 1];
        Opportunity opp = new Opportunity(
            Name = 'Test Opp',
            StageName = WON_STAGE,
            CloseDate = Date.today().addDays(30),
            AccountId = testAccount.Id,
            OwnerId = UserInfo.getUserId()
        );
        OpportunityWonHandler.beforeInsert(new List<Opportunity>{opp});
        System.assertEquals(HANDOVER_STEP, opp.NextStep, 'NextStep should be set for newly won opportunity on insert');
    }

    @isTest
    static void testAfterInsert_NewlyWonOpp() {
        Account testAccount = [SELECT Id, Rating FROM Account LIMIT 1];
        Opportunity opp = new Opportunity(
            Name = 'Test Opp',
            StageName = WON_STAGE,
            CloseDate = Date.today().addDays(30),
            AccountId = testAccount.Id,
            OwnerId = UserInfo.getUserId()
