public class AccountOnboardingService {

    public static List<Account> createAccountsWithContacts(Map<String, List<String>> contactLastNamesByAccountName) {
        // Return empty list if input is null or empty
        if (contactLastNamesByAccountName == null || contactLastNamesByAccountName.isEmpty()) {
            return new List<Account>();
        }

        // Create a new Unit of Work with Account and Contact SObject types
        fflib_SObjectUnitOfWork uow = new fflib_SObjectUnitOfWork(new Set<Type>{Account.SObjectType, Contact.SObjectType});

        List<Account> newAccounts = new List<Account>();

        // Iterate through each account name and its list of contact last names
        for (String accountName : contactLastNamesByAccountName.keySet()) {
            // Create the Account record
            Account newAccount = new Account(Name = accountName);
            uow.registerNew(newAccount);
            newAccounts.add(newAccount);

            // Create Contact records for each last name
            for (String lastName : contactLastNamesByAccountName.get(accountName)) {
                Contact newContact = new Contact(LastName = lastName);
                // Link the Contact to the Account using the Account's Id (which will be populated after commit)
                newContact.AccountId = newAccount.Id;
                uow.registerNew(newContact);
            }
        }

        // Commit all work in a single transaction
        uow.commitWork();

        return newAccounts;
    }
}
