public class PipelineSummary {
    public static Map<String, Decimal> totalsByStage(Date fromDate, Date toDate) {
        // The four stages we need to sum
        String[] stages = new String[] {
            'Prospecting',
            'Qualification',
            'Proposal/Price Quote',
            'Negotiation/Review'
        };

        Map<String, Decimal> result = new Map<String, Decimal>();

        // Loop over each stage and run an aggregate query
        for (String stage : stages) {
            // Aggregate query to sum Amount for opportunities in this stage within the date range
            // Using alias without AS keyword for SOQL compatibility
            AggregateResult ar = [
                SELECT SUM(Amount) totalAmount
                FROM Opportunity
                WHERE StageName = :stage
                AND CloseDate >= :fromDate
                AND CloseDate <= :toDate
            ];

            // Extract the sum using the alias key (could be null if no records) and default to 0
            Decimal sum = (Decimal) ar.get('totalAmount');
            if (sum == null) {
                sum = 0.0;
            }

            // Add to the result map
            result.put(stage, sum);
        }

        return result;
    }
}
