```apex
public class RenewalReminderService {

    public static Integer sendReminders(List<Id> opportunityIds) {
        Integer emailsSentSuccess = 0;

        // Query all opportunities in a single SOQL
        Map<Id, Opportunity> oppMap = new Map<Id, Opportunity>(
            [SELECT Id, OwnerId, Name, CloseDate 
             FROM Opportunity 
             WHERE Id IN :opportunityIds]
        );

        List<Messaging.SingleEmailMessage> emailBatch = new List<Messaging.SingleEmailMessage>();
        Integer invocationCount = 0;

        for (Id oppId : opportunityIds) {
            // Stop if we've already made 10 email invocations (governor limit)
            if (invocationCount >= 10) {
                break;
            }

            Opportunity opp = oppMap.get(oppId);
            if (opp == null) {
                continue;
            }

            // Create a single email message
            Messaging.SingleEmailMessage email = new Messaging.SingleEmailMessage();
            email.setTargetObjectId(opp.OwnerId);
            email.setSaveAsActivity(false);
            email.setSubject('Renewal due: ' + opp.Name);
            email.setPlainTextBody('The renewal for ' + opp.Name + ' is due on ' + opp.CloseDate);

            emailBatch.add(email);

            // Send batch when we reach 10 emails
            if (emailBatch.size() == 10) {
                try {
                    Messaging.sendEmail(emailBatch);
                    emailsSentSuccess += 10;
                    invocationCount++;
                } catch (Exception e) {
                    System.debug('Failed to send email batch: ' + e.getMessage());
                }
                emailBatch = new List<Messaging.SingleEmailMessage>();
            }
        }

        // Send any remaining emails if we haven't hit the invocation limit
        if (emailBatch.size() > 0 && invocationCount < 10) {
            try {
                Messaging.sendEmail(emailBatch);
                emailsSentSuccess += emailBatch.size();
                invocationCount++;
            } catch (Exception e) {
                System.debug('Failed to send remaining email batch: ' + e.getMessage());
            }
        }

        return emailsSentSuccess;
    }
}
