public with sharing class TA_Opportunity_CollectForErpSync implements TriggerAction.AfterInsert, TriggerAction.AfterUpdate {

    private static Set<Id> opportunityIdsToSync = new Set<Id>();

    public void afterInsert(List<SObject> triggerNew) {
        for (SObject sobj : triggerNew) {
            if (sobj instanceof Opportunity) {
                opportunityIdsToSync.add(sobj.Id);
            }
        }
    }

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        Map<Id, SObject> oldMap = new Map<Id, SObject>();
        for (SObject sobj : triggerOld) {
            oldMap.put(sobj.Id, sobj);
        }

        for (SObject sobj : triggerNew) {
            if (sobj instanceof Opportunity) {
                Opportunity newOpp = (Opportunity)sobj;
                Opportunity oldOpp = (Opportunity)oldMap.get(sobj.Id);
                if (newOpp.StageName != oldOpp.StageName) {
                    opportunityIdsToSync.add(sobj.Id);
                }
            }
        }
    }

    public static Set<Id> getOpportunityIdsToSync() {
        return opportunityIdsToSync;
    }

    public static void clearCollectedIds() {
        opportunityIdsToSync.clear();
    }
}
